import{_ as e,o as l,c as r,ag as n}from"./chunks/framework.CAXxHpAX.js";const x=JSON.parse('{"title":"408 统考操作系统 (Operating System) —— 知识库总览","description":"","frontmatter":{},"headers":[],"relativePath":"操作系统/index.md","filePath":"操作系统/index.md","lastUpdated":1785078490000}'),a={name:"操作系统/index.md"};function s(o,t,i,g,d,f){return l(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="_408-统考操作系统-operating-system-——-知识库总览" tabindex="-1">408 统考操作系统 (Operating System) —— 知识库总览 <a class="header-anchor" href="#_408-统考操作系统-operating-system-——-知识库总览" aria-label="Permalink to &quot;408 统考操作系统 (Operating System) —— 知识库总览&quot;">​</a></h1><blockquote><p>本资料库汇集了 408 考研《操作系统》科目的全部核心大纲知识点，涵盖操作系统概述、进程管理、内存管理、文件管理和输入输出管理五大板块。</p></blockquote><hr><h2 id="📂-理论模块" tabindex="-1">📂 理论模块 <a class="header-anchor" href="#📂-理论模块" aria-label="Permalink to &quot;📂 理论模块&quot;">​</a></h2><ul><li><strong><a href="./01_操作系统概述.html">01 操作系统概述</a></strong>：操作系统的概念、特征、功能；发展与分类；运行环境（内核态/用户态/中断/系统调用）；大内核与微内核。</li><li><strong><a href="./02_进程管理.html">02 进程管理</a></strong>：进程与线程概念、状态转换；进程同步与互斥（信号量/管程/经典问题）；处理机调度算法；死锁的预防、避免与检测。</li><li><strong><a href="./03_内存管理.html">03 内存管理</a></strong>：程序装入与链接；连续/非连续分配（分页/分段/段页式）；虚拟内存（请求分页/页面置换算法/抖动/工作集）。</li><li><strong><a href="./04_文件管理.html">04 文件管理</a></strong>：文件逻辑结构与物理结构；目录结构；文件存储空间管理；文件共享与保护。</li><li><strong><a href="./05_输入输出管理.html">05 输入输出管理</a></strong>：I/O 控制方式；I/O 软件层次；缓冲区管理；设备分配与回收；SPOOLing 技术；磁盘调度算法。</li></ul><h2 id="🎯-提分与回顾" tabindex="-1">🎯 提分与回顾 <a class="header-anchor" href="#🎯-提分与回顾" aria-label="Permalink to &quot;🎯 提分与回顾&quot;">​</a></h2><p><strong>分值分布</strong>（操作系统约 35 分）：进程管理（同步互斥 + 死锁）与内存管理（虚存 + 置换算法）是绝对重心，大题多出于此。</p><p><strong>必背速查</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">主题</th><th style="text-align:left;">一句话结论</th></tr></thead><tbody><tr><td style="text-align:left;">进程 vs 线程</td><td style="text-align:left;">进程是<strong>资源分配</strong>单位，线程是<strong>调度</strong>单位</td></tr><tr><td style="text-align:left;">五状态转换</td><td style="text-align:left;">就绪→运行（调度）、运行→就绪（时间片到）、运行→阻塞（<strong>主动</strong>）、阻塞→就绪（<strong>被动</strong>）</td></tr><tr><td style="text-align:left;">阻塞不能直接到运行</td><td style="text-align:left;">也不存在就绪→阻塞</td></tr><tr><td style="text-align:left;">PV 操作</td><td style="text-align:left;">互斥信号量初值 1；同步看&quot;前趋图&quot;，一条弧一个信号量</td></tr><tr><td style="text-align:left;">死锁四条件</td><td style="text-align:left;">互斥、不剥夺、请求并保持、循环等待（<strong>破坏任一</strong>即可预防）</td></tr><tr><td style="text-align:left;">银行家算法</td><td style="text-align:left;">属于死锁<strong>避免</strong>，不是预防也不是检测</td></tr><tr><td style="text-align:left;">页面置换</td><td style="text-align:left;">OPT 最优不可实现；LRU 需硬件支持；<strong>FIFO 会有 Belady 异常</strong></td></tr><tr><td style="text-align:left;">磁盘访问时间</td><td style="text-align:left;">寻道 + 旋转延迟 + 传输，旋转延迟平均为半圈</td></tr></tbody></table><p><strong>高频易错</strong></p><ol><li>分页的页大小由<strong>系统</strong>决定，分段的段长由<strong>用户/程序</strong>决定。</li><li>请求分页中，缺页中断属于<strong>内中断（异常）</strong>，且一条指令可能产生多次。</li><li>快表 TLB 命中时不访问页表；两级页表命中 TLB 仍只需一次访存取数据。</li><li>SPOOLing 把独占设备改造为<strong>共享</strong>设备，需要磁盘作输入/输出井。</li><li>时间片轮转的时间片过大会退化为 <strong>FCFS</strong>。</li><li>银行家算法判断的是&quot;是否处于<strong>安全状态</strong>&quot;，不安全 ≠ 一定死锁。</li></ol>',11)])])}const _=e(a,[["render",s]]);export{x as __pageData,_ as default};
